@startuml

class User {
  + Name : string
  + Email : string
}

class Student extends User {
}

class Tutor extends User {
  + BankAccount : string
}

class Subject {
  + Name : string
}

class TutoringOffer {
  + ExpertiseLevel : string
  + HourlyPrice : float
}

class Availability {
  + DayOfWeek : string
  + StartTime : time
  + EndTime : time
}

class TutoringRequest {
  + RequestedLevel : string
  + TargetDateTime : datetime
}

class TutoringSession {
  + ActualDateTime : datetime
  + Status : string
  + PaymentMethod : string
  + IsCancelled : boolean
  + CancellationTime : datetime
}

class Award {
  + Month : string
}

Student "1" -- "*" TutoringRequest : makes
Tutor "1" -- "*" TutoringRequest : receives
Tutor "1" -- "*" TutoringOffer : offers
Subject "1" -- "*" TutoringOffer : subject
Tutor "1" -- "*" Availability : specifies
TutoringOffer "1" -- "*" TutoringRequest : target
TutoringRequest "1" -- "0..1" TutoringSession : becomes
Student "1" -- "*" TutoringSession : attends
Tutor "1" -- "*" TutoringSession : conducts
Subject "1" -- "*" Award : awarded_in
Tutor "1" -- "*" Award : receives

@enduml

